f="/catatan-transaksi" class="flex min-w-[68px] shrink-0 flex-col items-center gap-1 px-1 pb-1 pt-2 text-[10px] font-medium text-muted"><span class="grid h-7 w-12 place-items-center rounded-full transition text-muted"><svg class="size-5 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 6a2 2 0 012-2h8l4 4v11a1 1 0 01-1 1H7a2 2 0 01-2-2V6z"/><path d="M9 13h6M9 17h4"/></svg></span><span class="whitespace-nowrap">Transaksi</span></a><a href="/laporan-keuangan" class="flex min-w-[68px] shrink-0 flex-col items-center gap-1 px-1 pb-1 pt-2 text-[10px] font-medium text-muted"><span class="grid h-7 w-12 place-items-center rounded-full transition text-muted"><svg class="size-5 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 20h16"/><path d="M5 16l4-4 3 3 6-7"/></svg></span><span class="whitespace-nowrap">Laporan</span></a><a href="/analisis-harga" class="flex min-w-[68px] shrink-0 flex-col items-center gap-1 px-1 pb-1 pt-2 text-[10px] font-medium text-muted"><span class="grid h-7 w-12 place-items-center rounded-full transition text-muted"><svg class="size-5 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="5" y="3.5" width="14" height="17" rx="2"/><path d="M8.5 8h7M8.5 12h2M13.5 12h2M8.5 16h2M13.5 16h2"/></svg></span><span class="whitespace-nowrap">Harga</span></a><a href="/analisis-stok-penjualan" class="flex min-w-[68px] shrink-0 flex-col items-center gap-1 px-1 pb-1 pt-2 text-[10px] font-medium text-muted"><span class="grid h-7 w-12 place-items-center rounded-full transition text-muted"><svg class="size-5 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="t